// Generates TypeScript types from the JSON Schemas in ../schemas into ../src/generated.
// Run with: npm run generate   (from packages/contracts)
// The schemas are the single source of truth; generated files are committed and must not be edited by hand.
import { mkdir, readdir, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { compileFromFile } from 'json-schema-to-typescript';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const schemaDir = path.join(root, 'schemas');
const outDir = path.join(root, 'src', 'generated');

const schemaFiles = (await readdir(schemaDir)).filter((f) => f.endsWith('.schema.json')).sort();

// Start clean so a removed schema cannot leave a stale generated file behind.
await rm(outDir, { recursive: true, force: true });
await mkdir(outDir, { recursive: true });

const moduleNames = [];
for (const file of schemaFiles) {
  const moduleName = file.replace('.schema.json', '');
  const banner =
    `/* Generated by scripts/generate-types.mjs from schemas/${file}. Do not edit by hand; run \`npm run generate\`. */`;
  const ts = await compileFromFile(path.join(schemaDir, file), {
    bannerComment: banner,
    additionalProperties: false,
    cwd: schemaDir,
  });
  await writeFile(path.join(outDir, `${moduleName}.ts`), ts, 'utf8');
  moduleNames.push(moduleName);
  console.log(`generated src/generated/${moduleName}.ts`);
}

const indexSource =
  `/* Generated by scripts/generate-types.mjs. Do not edit by hand; run \`npm run generate\`. */\n\n` +
  moduleNames.map((m) => `export type * from './${m}.js';`).join('\n') +
  '\n';
await writeFile(path.join(outDir, 'index.ts'), indexSource, 'utf8');
console.log('generated src/generated/index.ts');
